# 2. ฟังก์ชันจำลองข้อมูลคุณภาพแหล่งน้ำ (Water Records)
# ==========================================
def generate_water_mock_data(num_records=150):
    water_types = ["น้ำประปาผิวดิน", "น้ำประปาบาดาล", "น้ำบาดาลดิบ", "น้ำดื่มบรรจุขวด", "ตู้น้ำดื่มหยอดเหรียญ"]
    sources = ["อบต. อัปโหลด", "สำนักสุขาภิบาลอาหารและน้ำ", "สบส. เขต 1", "สบส. เขต 4", "โรงเรียนอัปโหลด"]
    
    records = []
    start_date = datetime.now() - timedelta(days=365)
    
    locs = random.sample(real_locations, min(num_records, len(real_locations)))
    for i in range(len(locs)):
        loc = locs[i]
        w_type = random.choice(water_types)
        
        # จำลองปริมาณฟลูออไรด์ (mg/L): ส่วนใหญ่ปลอดภัย (0.1 - 0.6) แต่จะมีบางจุดที่เกินมาตรฐาน (> 0.7)
        if loc["prov"] in ["เชียงใหม่", "นนทบุรี"] and random.random() < 0.35:
            # พื้นที่เฝ้าระวังฟลูออไรด์สูง
            fluoride_level = round(random.uniform(0.75, 2.5), 2)
        else:
            fluoride_level = round(random.uniform(0.05, 0.69), 2)
            
        status = "เกินมาตรฐาน" if fluoride_level >= 0.7 else "ปกติ"
        check_date = (start_date + timedelta(days=random.randint(0, 360))).strftime("%Y-%m-%d")
        
        house_no = f"{i + 1}/{random.randint(1, 50)}"
        moo = f"{random.randint(1, 12)}"
        
        records.append({
            "ลำดับ": i + 1,
            "ชนิดน้ำ": w_type,
            "สถานที่เก็บ": f"จุดตรวจชุมชน {loc['subdist']}",
            "ปริมาณฟลูออไรด์": fluoride_level,
            "ว/ด/ป ที่เก็บ": check_date,
            "บ้านเลขที่": house_no,
            "หมู่ที่": moo,
            "ตำบล": loc["subdist"],
            "อำเภอ": loc["dist"],
            "จังหวัด": loc["prov"],
            "เขตสุขภาพ": loc["zone"],
            "ภาค": loc["reg"],
            "ละติจูด": round(loc["lat"] + random.uniform(-0.015, 0.015), 5),
            "ลองจิจูด": round(loc["lon"] + random.uniform(-0.015, 0.015), 5),
            "หมายเหตุ": "เก็บตัวอย่างซ้ำ" if random.random() < 0.05 else "-",
            "แหล่งข้อมูล": random.choice(sources)
        })
        
    return pd.DataFrame(records)

# ==========================================
# 3. ฟังก์ชันจำลองข้อมูลทันตสุขภาพ (Dental Health Records)
# ==========================================
def generate_dental_mock_data(num_records=80):
    records = []
    
    locs = random.sample(real_locations, min(num_records, len(real_locations)))
    for i in range(len(locs)):
        loc = locs[i]
        fiscal_year = str(random.choice([2567, 2568, 2569]))
        
        total_kids = random.randint(150, 600)
        # สัดส่วนเด็กที่เข้ารับการตรวจ (70% - 95%)
        screened_kids = int(total_kids * random.uniform(0.70, 0.95))
        
        # จำลองการพบฟันตกกระ (สัมพันธ์กับพื้นที่ฟลูออไรด์สูง)
        if loc["prov"] in ["เชียงใหม่", "นนทบุรี"]:
            fluorosis_rate = random.uniform(0.08, 0.28) # ฟันตกกระ 8% - 28%
        else:
            fluorosis_rate = random.uniform(0.00, 0.05) # ฟันตกกระ 0% - 5%
            
        fluorosis_cases = int(screened_kids * fluorosis_rate)
        pct_fluorosis = round((fluorosis_cases / screened_kids * 100) if screened_kids > 0 else 0, 2)
        
        # กรณีรุนแรง (Severe cases)
        severe_cases = int(fluorosis_cases * random.uniform(0, 0.15))
        
        # Dean Index Status
        if pct_fluorosis > 20:
            status = "ระดับรุนแรง (Severe)"
        elif pct_fluorosis > 15:
            status = "ระดับปานกลาง (Moderate)"
        elif pct_fluorosis > 10:
            status = "ระดับอ่อน (Mild)"
        elif pct_fluorosis > 5:
            status = "ระดับอ่อนมาก (Very Mild)"
        else:
            status = "ปกติ (Normal)"
            
        records.append({
            "รหัสหน่วยบริการ": loc["hospcode"],
            "ชื่อหน่วยบริการ": loc["hname"],
            "ปีงบประมาณ": fiscal_year,
            "ภาค": loc["reg"],
            "เขตสุขภาพ": loc["zone"],
            "จังหวัด": loc["prov"],
            "อำเภอ": loc["dist"],
            "ตำบล": loc["subdist"],
            "ละติจูด": loc["lat"],
            "ลองจิจูด": loc["lon"],
            "จำนวนเด็กทั้งหมด": total_kids,
            "จำนวนตรวจ": screened_kids,
            "พบฟันตกกระ": fluorosis_cases,
            "สถานการณ์": status
        })
        
    return pd.DataFrame(records)

# ==========================================
# 4. เมนหลักสำหรับเขียนข้อมูล
# ==========================================
if __name__ == "__main__":
    print("Generating mock data for E-Fluoride...")
    
    # สร้างน้ำ
    df_water = generate_water_mock_data(100)
    water_path = "water_mock_data.xlsx"
    df_water.to_excel(water_path, index=False)
    print(f"Saved water mock data to {water_path} ({len(df_water)} rows)")
    
    # สร้างข้อมูลฟันเด็ก
    df_dental = generate_dental_mock_data(100)
    dental_path = "dental_data.xlsx"
    df_dental.to_excel(dental_path, index=False)
    print(f"Saved dental mock data to {dental_path} ({len(df_dental)} rows)")
    
    # เขียนไฟล์ของน้ำต้นฉบับด้วยเพื่อป้องกันการขาดแคลนข้อมูล
